insert into public.departments (id, organization_id, code, name_en, name_ar, description_en, description_ar, head_id, reports_to_id, responsibilities, contact_email, contact_extension, location_en, location_ar) values
  ('1725761f-0737-533a-940d-65b14608de91', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'OPS', 'Operations', 'العمليات', 'Runs the branch network day to day through regional Area Supervisors and sets operating standards.', 'تدير شبكة الفروع يوميًا من خلال مشرفي المناطق وتضع معايير التشغيل.', '36705be9-5001-59ba-a36d-623d14fd4ce3', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Network performance management and weekly reviews","ar":"إدارة أداء الشبكة والمراجعات الأسبوعية"},{"en":"Branch operating standards and SOPs","ar":"معايير تشغيل الفروع وإجراءاتها القياسية"},{"en":"Staffing models and shift coverage","ar":"نماذج التوظيف وتغطية المناوبات"},{"en":"Escalation management across regions","ar":"إدارة التصعيد بين المناطق"}]'::jsonb, 'ops@nexus-pharmacies.example', '1100', 'Nexus Tower, floor 9', 'برج نيكسس، الطابق 9'),
  ('fbbc2b16-e1ec-5c21-a5f6-458fb0ec0ffb', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'HR', 'Human Resources', 'الموارد البشرية', 'Attracts, retains and supports the people who run the branches, from hiring to performance management.', 'تستقطب الموظفين وتحافظ عليهم وتدعمهم، من التوظيف حتى إدارة الأداء.', 'fcbd935a-df95-5a3c-9b2e-bb9110b9fe7f', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Recruitment and onboarding of pharmacists","ar":"توظيف الصيادلة وتهيئتهم"},{"en":"Performance management cycles","ar":"دورات إدارة الأداء"},{"en":"Attendance, leave and payroll","ar":"الحضور والإجازات والرواتب"},{"en":"Employee relations and retention","ar":"علاقات الموظفين والمحافظة عليهم"}]'::jsonb, 'hr@nexus-pharmacies.example', '1200', 'Nexus Tower, floor 7', 'برج نيكسس، الطابق 7'),
  ('6e0970ee-91bf-5197-873f-126982d8fd80', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'SCM', 'Supply Chain', 'سلسلة الإمداد', 'Moves stock from distribution centre to shelf: replenishment, warehousing and inter-branch transfers.', 'تنقل المخزون من مركز التوزيع إلى الرف: إعادة التموين والتخزين والتحويلات بين الفروع.', 'ce71f647-812a-5b70-a21f-452beefefee4', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Automated replenishment and order planning","ar":"إعادة التموين الآلية وتخطيط الطلبات"},{"en":"Distribution centre operations","ar":"تشغيل مركز التوزيع"},{"en":"Inter-branch stock transfers","ar":"تحويلات المخزون بين الفروع"},{"en":"Cold-chain integrity","ar":"سلامة سلسلة التبريد"}]'::jsonb, 'scm@nexus-pharmacies.example', '1300', 'Nexus Tower, floor 4', 'برج نيكسس، الطابق 4'),
  ('a2c27a8b-c086-585c-8cab-5a1c24b90879', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'PUR', 'Purchasing', 'المشتريات', 'Negotiates with suppliers, manages product categories and decides the range each branch format carries.', 'تتفاوض مع الموردين وتدير فئات المنتجات وتحدد التشكيلة التي يحملها كل نوع من الفروع.', '173e6a51-9411-56fd-8fdd-ddb68cb36840', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Supplier negotiation and contracts","ar":"التفاوض مع الموردين والعقود"},{"en":"Category and range management","ar":"إدارة الفئات والتشكيلات"},{"en":"Pricing and promotional planning","ar":"التسعير وتخطيط العروض"},{"en":"Return-to-vendor agreements for expiring stock","ar":"اتفاقيات إرجاع المخزون قريب الانتهاء للموردين"}]'::jsonb, 'pur@nexus-pharmacies.example', '1400', 'Nexus Tower, floor 5', 'برج نيكسس، الطابق 5'),
  ('0d203294-94fd-5381-86b3-c66944143b63', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'MKT', 'Marketing', 'التسويق', 'Builds the Nexus brand, runs campaigns and the loyalty programme, and drives traffic to branches.', 'تبني علامة نيكسس وتدير الحملات وبرنامج الولاء وتجذب العملاء إلى الفروع.', '3977f659-aecf-5950-b1ef-628068d433a7', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Brand and seasonal campaigns","ar":"حملات العلامة والمواسم"},{"en":"Loyalty programme and customer CRM","ar":"برنامج الولاء وإدارة علاقات العملاء"},{"en":"In-store visual merchandising","ar":"العرض المرئي داخل الفروع"},{"en":"Digital channels and app promotions","ar":"القنوات الرقمية وعروض التطبيق"}]'::jsonb, 'mkt@nexus-pharmacies.example', '1500', 'Nexus Tower, floor 6', 'برج نيكسس، الطابق 6'),
  ('f348a361-2e59-5028-b98a-f4764dda6e78', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'FIN', 'Finance', 'المالية', 'Owns budgets, branch P&L reporting, inventory accounting and cost control.', 'مسؤولة عن الموازنات وتقارير أرباح وخسائر الفروع ومحاسبة المخزون وضبط التكاليف.', '564be480-c247-51ba-b3d9-ee88b254b582', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Annual budget and monthly forecasting","ar":"الموازنة السنوية والتوقعات الشهرية"},{"en":"Branch profit and loss reporting","ar":"تقارير أرباح وخسائر الفروع"},{"en":"Inventory valuation and write-offs","ar":"تقييم المخزون والشطب"},{"en":"Cost control and spend approval","ar":"ضبط التكاليف واعتماد الإنفاق"}]'::jsonb, 'fin@nexus-pharmacies.example', '1600', 'Nexus Tower, floor 8', 'برج نيكسس، الطابق 8'),
  ('6c34bcd8-3512-5658-8348-b9e5fe30bcb2', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'TND', 'Training & Development', 'التدريب والتطوير', 'Develops pharmacists'' clinical, service and leadership capabilities through structured programmes.', 'تطوّر القدرات السريرية والخدمية والقيادية للصيادلة من خلال برامج منظمة.', '1fe4cf25-86ae-56b8-8018-54b7e26ffdb3', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Onboarding academy for new pharmacists","ar":"أكاديمية تهيئة الصيادلة الجدد"},{"en":"Clinical and counseling programmes","ar":"البرامج السريرية وبرامج الإرشاد"},{"en":"Branch leader development pathway","ar":"مسار تطوير قادة الفروع"},{"en":"Mandatory compliance training tracking","ar":"متابعة التدريب الإلزامي على الامتثال"}]'::jsonb, 'tnd@nexus-pharmacies.example', '1700', 'Nexus Tower, floor 3', 'برج نيكسس، الطابق 3'),
  ('ce2ddc9a-05b3-5938-bf41-6d0838f84d0d', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'QAC', 'Quality & Compliance', 'الجودة والامتثال', 'Protects patients and the licence: audits, dispensing standards, pharmacovigilance and regulatory relations.', 'تحمي المرضى والترخيص: التدقيق ومعايير الصرف واليقظة الدوائية والعلاقة مع الجهات التنظيمية.', '171a41e1-8fa4-5baa-b981-64ef76451682', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', '[{"en":"Branch compliance audits","ar":"تدقيق امتثال الفروع"},{"en":"Dispensing and storage standards","ar":"معايير الصرف والتخزين"},{"en":"Pharmacovigilance and incident reporting","ar":"اليقظة الدوائية والإبلاغ عن الحوادث"},{"en":"Licences and regulatory inspections","ar":"التراخيص والتفتيش التنظيمي"}]'::jsonb, 'qac@nexus-pharmacies.example', '1800', 'Nexus Tower, floor 8', 'برج نيكسس، الطابق 8');
