insert into public.employee_profiles (employee_id, organization_id, summary_en, summary_ar, strengths, development_areas, communication_style, leadership_style, leadership_potential_score, leadership_potential, performance_score, career_aspiration, openness, conscientiousness, extraversion, agreeableness, emotional_stability, behavioral_traits) values
  ('a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Pharmacist turned executive who built Nexus from 40 to 120+ branches. Thinks in three-year horizons, expects regional leaders to bring options, not problems.', 'صيدلي تحوّل إلى قائد تنفيذي ونقل نيكسس من 40 إلى أكثر من 120 فرعًا. يفكر بأفق ثلاث سنوات ويتوقع من قادة المناطق تقديم خيارات لا مشكلات.', array['strategic_thinking','stakeholder_management','commercial_awareness']::text[], array['delegation']::text[], 'diplomatic', 'visionary', 83, 'high', 88, 'executive_leadership', 78, 74, 66, 52, 81, '{"motivators":["growth","recognition"],"stressTriggers":["unclear_priorities","public_criticism"],"conflictApproach":"confronting","decisionStyle":"data_driven"}'::jsonb),
  ('36705be9-5001-59ba-a36d-623d14fd4ce3', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Your direct manager. Runs a tight weekly performance review, reads every number, and has little patience for surprises. Rewards supervisors who escalate early with a plan.', 'مديرك المباشر. يدير مراجعة أداء أسبوعية دقيقة ويقرأ كل رقم ولا يحب المفاجآت. يقدّر المشرفين الذين يصعّدون مبكرًا ومعهم خطة.', array['data_literacy','planning','regulatory_compliance']::text[], array['team_coaching','conflict_resolution']::text[], 'direct', 'pacesetting', 81, 'high', 84, 'executive_leadership', 55, 86, 58, 47, 72, '{"motivators":["mastery","recognition"],"stressTriggers":["unclear_priorities","target_pressure"],"conflictApproach":"confronting","decisionStyle":"rule_based"}'::jsonb),
  ('c05e676d-a86c-598e-830b-bdfffbf07412', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Top-ranked supervisor for two years running. Delivers numbers through intensity and personal involvement; his teams perform but turnover is the highest in the network.', 'المشرف الأعلى تصنيفًا لعامين متتاليين. يحقق الأرقام بالحماس والمتابعة الشخصية، وفرقه تؤدي جيدًا لكن معدل دوران الموظفين لديه هو الأعلى في الشبكة.', array['sales_conversion','commercial_awareness','negotiation']::text[], array['team_coaching','conflict_resolution']::text[], 'direct', 'pacesetting', 84, 'high', 91, 'operations_management', 52, 78, 82, 34, 66, '{"motivators":["recognition","financial_reward"],"stressTriggers":["micromanagement","public_criticism"],"conflictApproach":"confronting","decisionStyle":"rule_based"}'::jsonb),
  ('b3449992-8bed-5930-86bf-64965656ec4d', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Builds people before numbers. Lowest staff turnover in the network and a steady upward trend; sometimes slow to address under-performance.', 'تبني الأشخاص قبل الأرقام. لديها أدنى معدل دوران موظفين في الشبكة واتجاه تصاعدي ثابت، لكنها أحيانًا تتأخر في معالجة ضعف الأداء.', array['team_coaching','conflict_resolution','patient_counseling']::text[], array['assertiveness','commercial_awareness']::text[], 'supportive', 'coaching', 76, 'high', 85, 'training_role', 74, 71, 57, 81, 70, '{"motivators":["growth","team_belonging"],"stressTriggers":["understaffing","target_pressure"],"conflictApproach":"collaborating","decisionStyle":"data_driven"}'::jsonb),
  ('d26595f3-2ae8-5330-b48f-4995a9fa34c6', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Newest supervisor, inherited the toughest region. Excellent with data and inventory, less comfortable in difficult conversations. Under visible pressure from the Operations Director.', 'أحدث المشرفين وورث المنطقة الأصعب. ممتاز في البيانات والمخزون وأقل ارتياحًا في المحادثات الصعبة. تحت ضغط واضح من مدير العمليات.', array['data_literacy','inventory_control','attention_to_detail']::text[], array['assertiveness','stress_management','stakeholder_management']::text[], 'analytical', 'democratic', 63, 'developing', 71, 'stable_role', 66, 82, 31, 63, 49, '{"motivators":["mastery","stability"],"stressTriggers":["target_pressure","last_minute_changes"],"conflictApproach":"accommodating","decisionStyle":"data_driven"}'::jsonb),
  ('336f196e-bf9d-5c51-9ace-08a1f2a570d0', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Yazeed brings 12 years of pharmacy experience. Colleagues rely on their planning & organisation and problem solving; the current development focus is punctuality.', 'يمتلك يزيد خبرة 12 سنة في العمل الصيدلي. يعتمد عليه الزملاء في التخطيط والتنظيم وحل المشكلات، ومحور التطوير الحالي هو الانضباط في المواعيد.', array['planning','problem_solving','strategic_thinking']::text[], array['punctuality','stress_management','inventory_control']::text[], 'diplomatic', null, 69, 'ready', 83, 'further_education', 60, 50, 56, 50, 60, '{"motivators":["mastery","growth","recognition"],"stressTriggers":["public_criticism","unclear_priorities"],"conflictApproach":"confronting","decisionStyle":"intuitive"}'::jsonb),
  ('29e1a21c-80c2-56c8-942d-18084bcc281e', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Haifa brings 12 years of pharmacy experience. Colleagues rely on their adaptability and patient counseling; the current development focus is assertiveness.', 'تمتلك هيفاء خبرة 12 سنة في العمل الصيدلي. يعتمد عليها الزملاء في المرونة والتكيّف وإرشاد المرضى، ومحور التطوير الحالي هو الحزم.', array['adaptability','patient_counseling','digital_tools']::text[], array['assertiveness','problem_solving','sales_conversion']::text[], 'analytical', null, 60, 'developing', 73, 'stable_role', 70, 66, 37, 72, 22, '{"motivators":["stability","growth"],"stressTriggers":["micromanagement","public_criticism"],"conflictApproach":"accommodating","decisionStyle":"data_driven"}'::jsonb),
  ('fcbd935a-df95-5a3c-9b2e-bb9110b9fe7f', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Policy-minded and fair. Will support tough people decisions if they are documented and consistent.', 'تهتم بالسياسات والعدالة. تدعم القرارات الصعبة المتعلقة بالموظفين إذا كانت موثقة ومتسقة.', array['stakeholder_management','conflict_resolution','planning']::text[], array['data_literacy']::text[], 'diplomatic', 'affiliative', 78, 'high', 82, 'executive_leadership', 62, 76, 54, 72, 74, '{"motivators":["team_belonging","stability"],"stressTriggers":["last_minute_changes","public_criticism"],"conflictApproach":"accommodating","decisionStyle":"data_driven"}'::jsonb),
  ('0063c2c0-c190-5a7b-89cd-c1a988c2c3f0', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Dana brings 10 years of pharmacy experience. Colleagues rely on their problem solving and regulatory compliance; the current development focus is inventory control.', 'تمتلك دانة خبرة 10 سنوات في العمل الصيدلي. يعتمد عليها الزملاء في حل المشكلات والالتزام التنظيمي، ومحور التطوير الحالي هو ضبط المخزون.', array['problem_solving','regulatory_compliance','digital_tools']::text[], array['inventory_control','time_management']::text[], 'diplomatic', null, 66, 'ready', 85, 'stable_role', 61, 34, 64, 54, 64, '{"motivators":["growth","stability"],"stressTriggers":["target_pressure","micromanagement"],"conflictApproach":"confronting","decisionStyle":"intuitive"}'::jsonb),
  ('05eb4fae-8d53-56a9-8921-aadf40d1699a', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Hatem brings 6 years of pharmacy experience. Colleagues rely on their problem solving and strategic thinking; the current development focus is assertiveness.', 'يمتلك حاتم خبرة 6 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في حل المشكلات والتفكير الاستراتيجي، ومحور التطوير الحالي هو الحزم.', array['problem_solving','strategic_thinking','data_literacy']::text[], array['assertiveness','digital_tools','delegation']::text[], 'analytical', null, 67, 'ready', 82, 'operations_management', 71, 80, 53, 59, 51, '{"motivators":["growth","recognition","mastery"],"stressTriggers":["stock_shortages","micromanagement"],"conflictApproach":"compromising","decisionStyle":"data_driven"}'::jsonb),
  ('bef7ee88-68aa-55f7-96ea-ca85ea9fac39', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Moayad brings 6 years of pharmacy experience. Colleagues rely on their data literacy and dermocosmetics; the current development focus is clinical knowledge.', 'يمتلك مؤيد خبرة 6 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في قراءة البيانات وتحليلها ومستحضرات العناية بالبشرة، ومحور التطوير الحالي هو المعرفة السريرية.', array['data_literacy','dermocosmetics','problem_solving']::text[], array['clinical_knowledge','customer_service']::text[], 'direct', null, 61, 'developing', 81, 'stable_role', 51, 52, 49, 33, 57, '{"motivators":["growth","mastery"],"stressTriggers":["target_pressure","last_minute_changes"],"conflictApproach":"compromising","decisionStyle":"intuitive"}'::jsonb),
  ('ce71f647-812a-5b70-a21f-452beefefee4', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Systems thinker who trusts the replenishment model over branch requests. Responds well to evidence, poorly to urgency without data.', 'يفكر بمنطق الأنظمة ويثق بنموذج إعادة التموين أكثر من طلبات الفروع. يستجيب للأدلة ولا يستجيب للاستعجال دون بيانات.', array['planning','inventory_control','data_literacy']::text[], array['stakeholder_management','adaptability']::text[], 'analytical', 'commanding', 76, 'high', 79, 'operations_management', 45, 84, 40, 50, 68, '{"motivators":["mastery","autonomy"],"stressTriggers":["last_minute_changes","unclear_priorities"],"conflictApproach":"compromising","decisionStyle":"rule_based"}'::jsonb),
  ('f55a1b8e-7837-50d0-aeca-5fb68e117699', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Manal brings 13 years of pharmacy experience. Colleagues rely on their patient counseling and problem solving; the current development focus is stress management.', 'تمتلك منال خبرة 13 سنة في العمل الصيدلي. يعتمد عليها الزملاء في إرشاد المرضى وحل المشكلات، ومحور التطوير الحالي هو إدارة الضغوط.', array['patient_counseling','problem_solving','planning']::text[], array['stress_management','inventory_control','stakeholder_management']::text[], 'supportive', null, 68, 'ready', 84, 'stable_role', 55, 61, 39, 73, 46, '{"motivators":["autonomy","growth"],"stressTriggers":["target_pressure","understaffing"],"conflictApproach":"accommodating","decisionStyle":"consensus"}'::jsonb),
  ('0e8e7dcc-7539-5626-b402-9100d7865407', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Hassan brings 10 years of pharmacy experience. Colleagues rely on their stakeholder management and commercial awareness; the current development focus is time management.', 'يمتلك حسن خبرة 10 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في إدارة أصحاب المصلحة والوعي التجاري، ومحور التطوير الحالي هو إدارة الوقت.', array['stakeholder_management','commercial_awareness','problem_solving']::text[], array['time_management','conflict_resolution','team_coaching']::text[], 'direct', null, 64, 'developing', 80, 'stable_role', 61, 36, 63, 45, 59, '{"motivators":["stability","growth"],"stressTriggers":["stock_shortages","understaffing"],"conflictApproach":"confronting","decisionStyle":"intuitive"}'::jsonb),
  ('4c7cff11-f994-533b-8908-d9ac7f682a84', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Muath brings 7 years of pharmacy experience. Colleagues rely on their cross-selling and delegation; the current development focus is inventory control.', 'يمتلك معاذ خبرة 7 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في البيع المتقاطع والتفويض، ومحور التطوير الحالي هو ضبط المخزون.', array['cross_selling','delegation','customer_service']::text[], array['inventory_control','planning']::text[], 'direct', null, 62, 'developing', 82, 'stable_role', 33, 35, 87, 40, 40, '{"motivators":["stability","autonomy","recognition"],"stressTriggers":["difficult_customers","target_pressure"],"conflictApproach":"confronting","decisionStyle":"intuitive"}'::jsonb),
  ('173e6a51-9411-56fd-8fdd-ddb68cb36840', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Commercially sharp and well connected with suppliers. Pushes promotional ranges that branches sometimes struggle to sell through.', 'حادّة تجاريًا وذات علاقات قوية مع الموردين. تدفع بتشكيلات ترويجية تجد الفروع صعوبة أحيانًا في تصريفها.', array['negotiation','commercial_awareness','strategic_thinking']::text[], array['attention_to_detail']::text[], 'expressive', 'visionary', 81, 'high', 86, 'executive_leadership', 70, 73, 69, 44, 71, '{"motivators":["financial_reward","autonomy"],"stressTriggers":["micromanagement","stock_shortages"],"conflictApproach":"confronting","decisionStyle":"data_driven"}'::jsonb),
  ('b46f6af7-a6c3-5466-9eba-983760868806', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Ahmed brings 7 years of pharmacy experience. Colleagues rely on their data literacy and stakeholder management; the current development focus is planning & organisation.', 'يمتلك أحمد خبرة 7 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في قراءة البيانات وتحليلها وإدارة أصحاب المصلحة، ومحور التطوير الحالي هو التخطيط والتنظيم.', array['data_literacy','stakeholder_management','stress_management']::text[], array['planning','attention_to_detail']::text[], 'expressive', null, 65, 'developing', 81, 'stable_role', 54, 25, 72, 62, 92, '{"motivators":["autonomy","patient_impact"],"stressTriggers":["understaffing","stock_shortages"],"conflictApproach":"collaborating","decisionStyle":"intuitive"}'::jsonb),
  ('71add09a-5de5-5d1f-8a7d-dabe03c34798', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Asma brings 8 years of pharmacy experience. Colleagues rely on their stakeholder management and digital & pos tools; the current development focus is stress management.', 'تمتلك أسماء خبرة 8 سنوات في العمل الصيدلي. يعتمد عليها الزملاء في إدارة أصحاب المصلحة والأدوات الرقمية وأنظمة البيع، ومحور التطوير الحالي هو إدارة الضغوط.', array['stakeholder_management','digital_tools','data_literacy']::text[], array['stress_management','problem_solving','adaptability']::text[], 'expressive', null, 69, 'ready', 76, 'operations_management', 60, 90, 66, 56, 41, '{"motivators":["mastery","stability"],"stressTriggers":["unclear_priorities","public_criticism"],"conflictApproach":"confronting","decisionStyle":"data_driven"}'::jsonb),
  ('c4468c59-ce16-5183-8d3e-464dc8a63d10', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Raed brings 10 years of pharmacy experience. Colleagues rely on their attention to detail and planning & organisation; the current development focus is commercial awareness.', 'يمتلك رائد خبرة 10 سنوات في العمل الصيدلي. يعتمد عليه الزملاء في الدقة والانتباه للتفاصيل والتخطيط والتنظيم، ومحور التطوير الحالي هو الوعي التجاري.', array['attention_to_detail','planning','regulatory_compliance']::text[], array['commercial_awareness','inventory_control','problem_solving']::text[], 'supportive', null, 74, 'high', 81, 'further_education', 53, 76, 60, 73, 74, '{"motivators":["mastery","recognition","patient_impact"],"stressTriggers":["last_minute_changes","stock_shortages"],"conflictApproach":"collaborating","decisionStyle":"rule_based"}'::jsonb),
  ('3977f659-aecf-5950-b1ef-628068d433a7', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'Creative and fast-moving. Launches campaigns quickly; branch readiness is not always checked in advance.', 'مبدع وسريع الحركة. يطلق الحملات بسرعة، ولا يتم دائمًا التحقق من جاهزية الفروع مسبقًا.', array['strategic_thinking','digital_tools','stakeholder_management']::text[], array['planning','attention_to_detail']::text[], 'expressive', 'visionary', 73, 'ready', 80, 'executive_leadership', 88, 55, 84, 61, 63, '{"motivators":["recognition","autonomy"],"stressTriggers":["micromanagement","unclear_priorities"],"conflictApproach":"collaborating","decisionStyle":"intuitive"}'::jsonb),
