insert into public.relationships (id, organization_id, source_id, target_id, relationship_type, trust, rapport, description_en, description_ar) values
  ('c986ed37-eb66-5ecc-86ab-b420ba137d8d', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '36705be9-5001-59ba-a36d-623d14fd4ce3', 'a5f8cae9-3eaa-50d5-90d4-6a63b60b5962', 'manager', 74, 61, 'Trusted lieutenant; the CEO relies on him for network-wide execution.', 'ذراع تنفيذي موثوق؛ يعتمد عليه الرئيس التنفيذي في التنفيذ على مستوى الشبكة.'),
  ('ba496e56-4d15-5055-884a-a7485bd1b39d', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '36705be9-5001-59ba-a36d-623d14fd4ce3', 'manager', 50, 45, 'New reporting relationship. He expects a 30-day diagnosis of your region and no surprises in weekly reviews.', 'علاقة إدارية جديدة. يتوقع منك تشخيصًا لمنطقتك خلال 30 يومًا ودون مفاجآت في المراجعات الأسبوعية.'),
  ('6dc8705d-5386-5b24-8588-4422691f9215', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', 'c05e676d-a86c-598e-830b-bdfffbf07412', 'rivalry', 28, 35, 'Competitive. Shares results openly but guards methods; sees you as the main rival for the next promotion.', 'علاقة تنافسية. يشارك النتائج علنًا لكنه يحتفظ بأساليبه؛ يراك المنافس الأبرز على الترقية القادمة.'),
  ('2e0df51e-e6e3-553b-9951-e599966472fd', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', 'b3449992-8bed-5930-86bf-64965656ec4d', 'collaboration', 72, 68, 'Natural ally. Happy to share coaching tools and lend a trainer; expects reciprocity on stock transfers.', 'حليفة طبيعية. تشارك أدوات التوجيه بسهولة وقد تعير مدربًا؛ وتتوقع المعاملة بالمثل في تحويلات المخزون.'),
  ('d7fe1c1b-bf17-5b62-86ce-ea9e02d2b9ac', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', 'd26595f3-2ae8-5330-b48f-4995a9fa34c6', 'peer', 54, 47, 'Cordial and cautious. Often asks for your view on analytics; could become a strong ally or withdraw under pressure.', 'علاقة ودية وحذرة. يطلب رأيك كثيرًا في التحليلات؛ قد يصبح حليفًا قويًا أو ينسحب تحت الضغط.'),
  ('39790c58-b86c-5b42-b458-e3144d9151ed', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'c05e676d-a86c-598e-830b-bdfffbf07412', 'd26595f3-2ae8-5330-b48f-4995a9fa34c6', 'friction', 22, 30, 'Openly compares regional rankings in leadership meetings, which Faisal finds demoralising.', 'يقارن ترتيب المناطق علنًا في اجتماعات القيادة، وهو ما يجده فيصل محبطًا.'),
  ('bdb7363a-eedd-5611-a061-bc42465c44a0', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'b3449992-8bed-5930-86bf-64965656ec4d', 'd26595f3-2ae8-5330-b48f-4995a9fa34c6', 'mentorship', 70, 64, 'Noura informally coaches Faisal on difficult staff conversations.', 'تقدّم نورة توجيهًا غير رسمي لفيصل في المحادثات الصعبة مع الموظفين.'),
  ('0b363a91-8bb5-58b5-a050-3ff01f1f66a9', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '336f196e-bf9d-5c51-9ace-08a1f2a570d0', 'collaboration', 58, 52, 'Owns the SOP library and audit follow-ups for your region.', 'مسؤول عن مكتبة الإجراءات ومتابعة التدقيق في منطقتك.'),
  ('0950004f-784a-5327-8bec-6dcc28638fa3', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '0063c2c0-c190-5a7b-89cd-c1a988c2c3f0', 'collaboration', 61, 64, 'Your first call for performance cases, transfers and recruitment.', 'جهة الاتصال الأولى لحالات الأداء والنقل والتوظيف.'),
  ('f03b6c7d-c95c-5329-819c-56f1d51a5e4f', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '0e8e7dcc-7539-5626-b402-9100d7865407', 'collaboration', 44, 40, 'Controls delivery slots for your branches; responsive when given notice.', 'يتحكم في مواعيد التوريد لفروعك؛ يتجاوب عند إبلاغه مسبقًا.'),
  ('faf75ae6-bdb8-5e86-b4a8-0b3e41c34541', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '71add09a-5de5-5d1f-8a7d-dabe03c34798', 'collaboration', 39, 50, 'Allocates promotional stock; your slow-moving beauty stock is a recurring topic.', 'توزع مخزون العروض؛ مخزون التجميل بطيء الحركة لديك موضوع متكرر بينكما.'),
  ('bf1474e0-4b1c-51f0-ab18-cfcf197d3bfc', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '4521abeb-89ea-5123-a1be-24304f26ea9c', 'collaboration', 50, 42, 'Prepares your monthly branch P&L pack.', 'تُعدّ حزمة أرباح وخسائر فروعك الشهرية.'),
  ('7a623fb8-5e99-59ed-83f1-829dd4ee9c53', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', '6403c5ec-70da-5114-92e2-19c52ea00b96', 'collaboration', 66, 70, 'Runs counseling refreshers in your branches on request.', 'يقدم دورات إرشاد المرضى في فروعك عند الطلب.'),
  ('9c744596-ef41-54b4-8714-1a89b77cc579', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', 'c99f8ade-34b8-511e-80db-c973a751a27f', 'collaboration', 47, 38, 'Conducts your branches'' unannounced audits.', 'تُجري التدقيقات المفاجئة على فروعك.'),
  ('baa0c4bb-662c-50d7-816d-854f0de4420b', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '17a7a272-e089-5f63-9941-c827a21488e4', 'f1f22ec5-b04b-5eec-a78c-288fdc03f7ae', 'manager', 65, 51, 'Confident and proud of results; wants autonomy more than direction.', 'واثق وفخور بالنتائج؛ يريد الاستقلالية أكثر من التوجيه.'),
  ('26c17a17-5c3e-5c3b-8e6a-1e207a8479a1', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'f1f22ec5-b04b-5eec-a78c-288fdc03f7ae', '27cda116-37b7-5363-8215-e2aa76e627d4', 'manager', 27, 23, 'Solid working relationship with occasional friction on priorities.', 'علاقة عمل جيدة مع احتكاك أحيانًا حول الأولويات.'),
  ('6958ab1e-7c08-5774-8524-edb2eb977cae', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'f1f22ec5-b04b-5eec-a78c-288fdc03f7ae', '057dd250-e1b8-5494-aa2d-398f2f28d892', 'manager', 52, 45, 'Relies on them for key shifts.', 'يعتمد عليه في المناوبات المهمة.'),
  ('29a7abb7-4af8-5bb1-84a4-573f7d40311f', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', 'f1f22ec5-b04b-5eec-a78c-288fdc03f7ae', '14705999-9f43-5e41-bd6b-0a3a36905293', 'manager', 36, 28, 'Solid working relationship with occasional friction on priorities.', 'علاقة عمل جيدة مع احتكاك أحيانًا حول الأولويات.'),
  ('9ff54e27-ea9a-5b3f-9ad1-c879a21bdbbd', 'fb1a2143-04d4-5c46-8c77-bbea10471bbb', '27cda116-37b7-5363-8215-e2aa76e627d4', '14705999-9f43-5e41-bd6b-0a3a36905293', 'mentorship', 72, 64, 'Informal mentor on dispensing and counseling.', 'مرشد غير رسمي في الصرف والإرشاد.'),
